// Isolated contract verification for Declared-Product Rescue reports
// (extraction.method = "declared_product_dom") through the REAL
// Workspace claim validation and Save/Review API layer. Transport is
// a synthetic in-memory stub; hosted persistence is not proven here
// (native-stack and hosted Part C evidence cover RPC persistence for
// the same payload shape). The adapter report is generated by the
// real Python adapter from the recorded Landyachtz HTML fixture.
import test from 'node:test';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {mkdtempSync, readFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';

const store = new Map();
globalThis.sessionStorage = {
  getItem: k => (store.has(k) ? store.get(k) : null),
  setItem: (k, v) => store.set(k, String(v)),
  removeItem: k => store.delete(k),
};

const outDir = mkdtempSync(join(tmpdir(), 'declared-product-'));
const reportPath = join(outDir, 'report.json');
execFileSync('python3', ['-c', `
import sys, json
sys.path.insert(0, 'prototype/public-audit')
from first_result_api import build_snapshot
body = open('prototype/public-audit/fixtures/landyachtz-the-clark.html', 'rb').read()
def fixture(url):
    if url.endswith('/robots.txt'):
        return 200, {'content-type': 'text/plain'}, b'User-agent: *\\nAllow: /\\n'
    return 200, {'content-type': 'text/html'}, body
report = build_snapshot('https://landyachtz.com/shop/all/skate/boards/all-skate-boards/the-clark/', fixture, lambda: '2026-10-19T00:00:00Z')
assert report['page_type'] == 'product' and report['extraction']['method'] == 'declared_product_dom', report['page_type']
open('${reportPath}', 'w').write(json.dumps(report))
`], {cwd: new URL('../../', import.meta.url), encoding: 'utf8'});

const report = JSON.parse(readFileSync(reportPath, 'utf8'));
const {createResultReview, reviewFields} = await import('../../apps/web/first-result-review.mjs');
const {validateReport} = await import('../../apps/web/first-result-payload.mjs');
const {createWorkspaceApi} = await import('../../apps/web/claim-guarded-workspace-api.mjs');

const USER = '11111111-1111-4111-8111-111111111111';
const ORG = '22222222-2222-4222-8222-222222222222';
const OPP = '33333333-3333-4333-8333-333333333333';
const VERSION = '44444444-4444-4444-8444-444444444444';
const REVIEW = '55555555-5555-4555-8555-555555555555';
const CHECKS = {title: true, meta_description: true, description: true, source: true, blocking_facts_clear: true};
let saveBody = null, reviewBody = null, savedRow = null, reviewRow = null;

const jsonResponse = value => new Response(JSON.stringify(value), {status: 200, headers: {'content-type': 'application/json'}});
async function stubFetch(url, init = {}) {
  const u = new URL(url);
  const method = init.method || 'GET';
  if (u.pathname === '/auth/v1/user') return jsonResponse({id: USER});
  if (u.pathname === '/rest/v1/organization_members') return jsonResponse([{organization_id: ORG, role: 'owner'}]);
  if (u.pathname === '/rest/v1/growth_opportunities') return jsonResponse([{id: OPP, entry_kind: 'url_result'}]);
  if (method === 'POST' && u.pathname === '/rest/v1/rpc/save_url_result_draft') {
    saveBody = JSON.parse(init.body);
    savedRow = {organization_id: ORG, id: VERSION, opportunity_id: saveBody.p_opportunity_id,
      version_number: 1, title: saveBody.p_payload.preview.fields.title.suggested,
      draft_body: saveBody.p_payload.preview.fields.description.suggested, status: 'draft',
      created_at: '2026-10-19T00:00:00.000Z', first_result_request_id: saveBody.p_request_id,
      first_result_expected_version: saveBody.p_expected_version,
      first_result_request_digest: 'pg-jsonb-sha256:' + 'a'.repeat(64), first_result_payload: saveBody.p_payload};
    return jsonResponse(VERSION);
  }
  if (method === 'POST' && u.pathname === '/rest/v1/rpc/review_url_result') {
    reviewBody = JSON.parse(init.body);
    reviewRow = {id: REVIEW, organization_id: ORG, version_id: VERSION, actor_user_id: USER,
      decision: 'approved', reason: null, reviewed_at: '2026-10-19T00:00:00.000Z',
      url_review_request_id: reviewBody.p_request_id, url_review_source_digest: reviewBody.p_source_digest,
      url_review_content_digest: reviewBody.p_content_digest, url_review_version_digest: reviewBody.p_version_digest,
      url_review_checks: CHECKS};
    return jsonResponse(REVIEW);
  }
  if (u.pathname === '/rest/v1/content_versions') {
    if (u.searchParams.get('select') === 'id,version_number') return jsonResponse([{id: VERSION, version_number: 1}]);
    return jsonResponse(savedRow ? [savedRow] : []);
  }
  if (u.pathname === '/rest/v1/content_reviews') return jsonResponse(reviewRow ? [reviewRow] : []);
  throw new Error('unexpected stub path ' + u.pathname);
}

test('declared-product report passes claim validation and isolated Save/Review contract', async () => {
  const review = createResultReview(report);
  for (const key of reviewFields) review.check(key, true);
  await review.confirm();
  const exported = await review.export();
  assert.equal(exported.extraction.method, 'declared_product_dom');
  await validateReport(exported); // must not throw after the approved exception

  const api = createWorkspaceApi({origin: 'https://vhzryhibmpvglzcmfnaa.supabase.co',
    key: 'sb_publishable_contract_probe', redirectOrigin: 'http://127.0.0.1:4321',
    fetchImpl: stubFetch, urlSaveEnabled: true, urlResultSchemaEnabled: true, urlReviewEnabled: true});
  await api.completeMagicLink('#access_token=contract-token&token_type=bearer&expires_in=3600');

  const intent = {organization_id: ORG, opportunity_id: OPP,
    request_id: '66666666-6666-4666-8666-666666666666', expected_version: 0, payload: exported};
  const versionId = await api.saveUrlResult(intent, {isCurrent: () => true});
  assert.equal(versionId, VERSION);
  assert.equal(saveBody.p_payload.extraction.method, 'declared_product_dom');

  const reconciled = await api.reconcileUrlResult(intent, versionId);
  assert.equal(reconciled.id, VERSION);
  assert.equal(reconciled.title, 'The Clark');

  const reviewId = await api.confirmUrlReview(reconciled, CHECKS, {isCurrent: () => true});
  assert.equal(reviewId, REVIEW);
  assert.equal(reviewBody.p_source_digest, exported.snapshot.content_fingerprint);
  assert.equal(reviewBody.p_content_digest, exported.review.content_digest);

  const readback = await api.readUrlReview(reconciled, {isCurrent: () => true});
  assert.equal(readback.id, REVIEW);
  assert.equal(readback.decision, 'approved');
});


test('declared-product aggregate keeps every paragraph citation and exact payload through guard',async()=>{
 const {assertSavedClaims}=await import('../../apps/web/saved-claim-context.mjs');
 const review=createResultReview(report);for(const key of reviewFields)review.check(key,true);await review.confirm();
 const payload=await review.export(),before=JSON.stringify(payload);
 assert.ok(report.facts.description.citations.length>2,'recorded source has supplemental paragraph');
 const result=await assertSavedClaims(payload);assert.equal(result.mapping_status,'PROVEN_EXTRACTIVE_CONTEXT');
 assert.equal(JSON.stringify(payload),before);
});
test('declared-product supplemental paragraphs cannot replace full evidence or add unrelated support',async()=>{
 const {createConsoleSourceContext}=await import('../../apps/web/console-claim-review.mjs');
 const description=report.facts.description,nameIds=report.facts.product_name.citations;
 const ids=description.citations.filter(id=>!nameIds.includes(id));assert.ok(ids.length>1);
 const corruptions=[
  r=>r.snapshot.citations.find(c=>c.id===ids[1]).quote='Unrelated claim.',
  r=>r.facts.description.citations=r.facts.description.citations.filter(id=>id!==ids[0]),
  r=>r.snapshot.citations.find(c=>c.id===ids[0]).quote='Partial quote.',
  r=>r.snapshot.citations.find(c=>c.id===ids[1]).locator=r.snapshot.citations.find(c=>c.id===ids[0]).locator,
  r=>r.facts.description.citations=[ids[1],ids[0],...nameIds],
  r=>r.facts.description.citations=r.facts.description.citations.filter(id=>!nameIds.includes(id)),
 ];
 for(const corrupt of corruptions){const r=structuredClone(report);corrupt(r);assert.throws(()=>createConsoleSourceContext(r));}
});
